import{_ as r,c as t,o,a4 as n}from"./chunks/framework.BU14wsQo.js";const e="/ai/daily/2026-05-13/news_01krfemqmxesqahb4j5gysdtnw.avif",s="/ai/daily/2026-05-13/news_01krfjhtvyesqahb6cwk55ep9w.mp4",i="/ai/daily/2026-05-13/news_01krfjfjzfesqahb4tbm18g4gj.avif",l="/ai/daily/2026-05-13/news_01krfjfrxqesqahb501e1xxzs5.avif",h="/ai/daily/2026-05-13/news_01krfjfvvzesqahb5bp7kmc5z5.avif",p="/ai/daily/2026-05-13/news_01krfjgadyesqahb5natgb92f7.avif",d="/ai/daily/2026-05-13/news_01krfjgdgaesqahb5xramvq1tg.avif",c="/ai/daily/2026-05-13/news_01krfjgfttesqahb67t6ff9kpm.avif",I=JSON.parse('{"title":"AI大事件 2026/5/13","description":"DuckDB Quack、Claude Opus 4.7、Step Image Edit 2 与多项产品更新推动 AI 入口扩张；FrontierMath 修正、韩国 AI 税、npm 投毒与 OpenAI 调查同步抬高行业治理强度。","frontmatter":{"linkTitle":"05-13 AI大事件","title":"AI大事件 2026/5/13","weight":19,"breadcrumbs":false,"comments":true,"description":"DuckDB Quack、Claude Opus 4.7、Step Image Edit 2 与多项产品更新推动 AI 入口扩张；FrontierMath 修正、韩国 AI 税、npm 投毒与 OpenAI 调查同步抬高行业治理强度。"},"headers":[],"relativePath":"AI/daily/cn/2026-05/2026-05-13.md","filePath":"AI/daily/cn/2026-05/2026-05-13.md","lastUpdated":1778646796000}'),g={name:"AI/daily/cn/2026-05/2026-05-13.md"};function u(m,a,b,f,_,k){return o(),t("div",null,[...a[0]||(a[0]=[n(`<h1 align="center">2026-05-13 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DuckDB 的 Quack 协议、Claude Opus 4.7、载人机甲和 Android 新助手同日冒头，AI 产品入口继续全面外扩 🚀</span></span>
<span class="line"><span>Step Image Edit 2、Perceptron Mk1、MatterSim 与 FrontierMath 校准风波，把模型能力、科研效率与评测可信度同时推到台前 🧠</span></span>
<span class="line"><span>OpenAI、DeepSeek、腾讯、AWS、Meta 与 Google 一边扩平台一边扛治理压力，行业竞争明显转向系统化落地 ☁️</span></span>
<span class="line"><span>从 Statewright、Codex、Cursor Teams 到官方插件联动，开发者工作流继续朝多智能体协作和跨应用自动化演进 🛠️</span></span>
<span class="line"><span>药物建议致死诉讼、npm 投毒、AI 犯罪辅助与平台利益调查提醒大家：AI 越能行动，安全、责任与审计越不能缺席 ⚠️</span></span>
<span class="line"><span>社媒侧从 Token 使用、HTML 输出到消费数据导出与开放模型生态，讨论重心正在从“能不能做”转向“怎么长期做对” ✨</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-duckdb-发布-quack-协议" tabindex="-1">1. DuckDB 发布 Quack 协议 <a class="header-anchor" href="#_1-duckdb-发布-quack-协议" aria-label="Permalink to &quot;1. DuckDB 发布 Quack 协议&quot;">​</a></h3><p>嵌入式数据库迎来 跨端远程查询() 进化。 <strong>Quack 协议</strong> ⚓️ 配合 <strong>DuckLake</strong> 减少开销。历史参考提到的架构演进 (✪ω✪) 终成现实。 <strong>Wasm</strong> 版本配合 <strong>HTTP/2</strong> 性能超级强 来源包括：<a href="https://newshacker.me/story?id=48111765" target="_blank" rel="noreferrer">跨端远程查询(AI 资讯)</a>。</p><h3 id="_2-meta-升级数据摄取系统" tabindex="-1">2. Meta 升级数据摄取系统 <a class="header-anchor" href="#_2-meta-升级数据摄取系统" aria-label="Permalink to &quot;2. Meta 升级数据摄取系统&quot;">​</a></h3><p><strong>Meta</strong> 成功迁移了 系统升级成功() 数据。 影子测试 🚀 保证了迁移过程零误差。自动化工具监控上万任务 (^_−)☆ 调度资源。这为 <strong>大模型训练</strong> 提供了坚实底座 来源包括：<a href="https://engineering.fb.com/2026/05/12/data-infrastructure/migrating-data-ingestion-systems-at-meta-scale/" target="_blank" rel="noreferrer">系统升级成功(AI 资讯)</a>。</p><p><img src="`+e+'" alt="AI资讯：AI资讯：Meta大规模数据迁移生命周期流程图" loading="lazy"></p><h3 id="_3-claude-opus-4-7-快速模式" tabindex="-1">3. Claude Opus 4.7 快速模式 <a class="header-anchor" href="#_3-claude-opus-4-7-快速模式" aria-label="Permalink to &quot;3. Claude Opus 4.7 快速模式&quot;">​</a></h3><p><strong>快速模式</strong> 预览版已在 API 和代码环境() 上线。 <strong>Opus 模型</strong> ✨ 响应速度得到了大幅度提升。这让 <strong>智能代码</strong> 开发变得极其丝滑。开发者无需等待 (o ﾟ ▽ ﾟ)o 即可高效反馈 来源包括：<a href="https://x.com/alexalbert__/status/2054268569337389487" target="_blank" rel="noreferrer">API 和代码环境(AI 资讯)</a>。</p><h3 id="_4-宇树科技发布载人机甲" tabindex="-1">4. 宇树科技发布载人机甲 <a class="header-anchor" href="#_4-宇树科技发布载人机甲" aria-label="Permalink to &quot;4. 宇树科技发布载人机甲&quot;">​</a></h3><p><strong>GD01 机甲</strong> 🦾 开启了 <strong>量产载人机器人</strong> 时代。官方定价 三百九十万 元引全网围观。 <strong>双足模式</strong> 💥 甚至能一拳干碎厚砖墙。科幻座舱操控感 😲 简直是男人的浪漫 来源包括：<a href="https://x.com/_FORAB/status/2054083833566552264" target="_blank" rel="noreferrer">量产载人机器人</a>。</p><h3 id="_5-aws-云平台集成-claude" tabindex="-1">5. AWS 云平台集成 Claude <a class="header-anchor" href="#_5-aws-云平台集成-claude" aria-label="Permalink to &quot;5. AWS 云平台集成 Claude&quot;">​</a></h3><p>亚马逊 <strong>AWS</strong> 现已支持 <strong>免密钥调用</strong> 克劳德服务。用户无需注册账号 (｡♥‿♥｡) 即可快速部署。 云端整合 🚀 极大的降低了模型使用门槛。顶级模型通过 <strong>AWS 控制台</strong> 即可获取 来源包括：<a href="https://x.com/abskoop/status/2054141275688034702" target="_blank" rel="noreferrer">免密钥调用</a>。</p><h3 id="_6-claude-opus-4-7-快速模式开放研究预览" tabindex="-1">6. Claude Opus 4.7 快速模式开放研究预览 <a class="header-anchor" href="#_6-claude-opus-4-7-快速模式开放研究预览" aria-label="Permalink to &quot;6. Claude Opus 4.7 快速模式开放研究预览&quot;">​</a></h3><p><strong>Claude Opus 4.7</strong> 的快速模式现已在 <strong>API</strong> 和 <strong>Claude Code</strong> 中开放研究预览。 来源：<a href="https://x.com/ClaudeDevs/status/2054266327771275435" target="_blank" rel="noreferrer">X：Claude Devs (@ClaudeDevs)</a>。</p><h3 id="_7-step-image-edit-2-图像模型发布-性能领先且高效" tabindex="-1">7. Step Image Edit 2 图像模型发布，性能领先且高效 <a class="header-anchor" href="#_7-step-image-edit-2-图像模型发布-性能领先且高效" aria-label="Permalink to &quot;7. Step Image Edit 2 图像模型发布，性能领先且高效&quot;">​</a></h3><p><strong>Step Image Edit 2</strong> 模型正式发布。这是一个 35 亿参数的图像模型，在指令式图像编辑的权威基准 <strong>KRIS-Bench</strong> 中，于综合、事实和概念类别均排名第一，性能超越参数量为其 5-6 倍的模型。其核心能力包括文生图、基于指令的图像编辑、精准的中英双语文字渲染以及保持主体一致性的风格迁移。该模型生成速度快，单次编辑成本低，目前已上线 <strong>Stepfun 开放平台</strong>。 来源：<a href="https://x.com/StepFun_ai/status/2054282965652471918" target="_blank" rel="noreferrer">X：阶跃星辰 StepFun (@StepFun_ai)</a>。</p><h3 id="_8-thinking-machines-发布原生多模态-交互模型-实现实时人机协作" tabindex="-1">8. Thinking Machines 发布原生多模态“交互模型”，实现实时人机协作 <a class="header-anchor" href="#_8-thinking-machines-发布原生多模态-交互模型-实现实时人机协作" aria-label="Permalink to &quot;8. Thinking Machines 发布原生多模态“交互模型”，实现实时人机协作&quot;">​</a></h3><p>前 <strong>OpenAI CTO Mira</strong> 创立的 <strong>Thinking Machines</strong> 公司发布了一种创新的“交互模型”。该模型能原生、持续地接收音频、视频和文本等多模态输入，并实时思考与响应，而非通过 <strong>Agent</strong> 串联多个独立模型。其架构分为两部分：前台交互模型以 200 毫秒为节点处理输入并维持用户“在场感”，支持随时打断；后台推理模型则处理长程规划、工具调用等复杂任务。两者协同工作，最终呈现为一个既能实时交互又能处理重度任务的统一界面。 来源：<a href="https://x.com/op7418/status/2054023602874491326" target="_blank" rel="noreferrer">X：歸藏 (@op7418)</a>。</p><h3 id="_9-perceptron-mk1-视觉语言模型上线-openrouter" tabindex="-1">9. Perceptron Mk1 视觉语言模型上线 OpenRouter <a class="header-anchor" href="#_9-perceptron-mk1-视觉语言模型上线-openrouter" aria-label="Permalink to &quot;9. Perceptron Mk1 视觉语言模型上线 OpenRouter&quot;">​</a></h3><p><strong>Perceptron Mk1</strong> 已在 <strong>OpenRouter</strong> 上线，由 @perceptroninc 开发。 前沿视频与具身推理的视觉语言模型。以动态帧率（最高 2 FPS）分析视频，具备 <strong>32k 多模态上下文</strong>，采用混合推理和结构化空间基元（点、框、多边形、片段）作为首要输出。 来源：<a href="https://x.com/OpenRouter/status/2054232344148787462" target="_blank" rel="noreferrer">X：OpenRouter (@OpenRouter)</a>。</p><h3 id="_10-材料科学-ai-多任务模型突破" tabindex="-1">10. 材料科学 AI 多任务模型突破 <a class="header-anchor" href="#_10-材料科学-ai-多任务模型突破" aria-label="Permalink to &quot;10. 材料科学 AI 多任务模型突破&quot;">​</a></h3><p><strong>MatterSim</strong> 正在拓展 AI 在材料科学中的应用边界——从更快速的大规模模拟，到全新多任务模型 <strong>MatterSim-MT</strong>，可模拟超越势能面的多种物性。<a href="https://msft.it/6017vPamT" target="_blank" rel="noreferrer">https://msft.it/6017vPamT</a> 来源：<a href="https://x.com/MSFTResearch/status/2054191008091418998" target="_blank" rel="noreferrer">X：Microsoft Research (@MSFTResearch)</a>。</p><h3 id="_11-谷歌-ai-重塑智能鼠标指针交互" tabindex="-1">11. 谷歌 AI 重塑智能鼠标指针交互 <a class="header-anchor" href="#_11-谷歌-ai-重塑智能鼠标指针交互" aria-label="Permalink to &quot;11. 谷歌 AI 重塑智能鼠标指针交互&quot;">​</a></h3><p>团队正在用 AI 重新构想鼠标指针，成果非常酷！在 <strong>@GoogleAIStudio</strong> 尝试原型版本，体验相当神奇。 [引用 @GoogleDeepMind]：我们正用 AI 重新构想这个存在 50 年的界面——鼠标指针。🖱️ 这些实验演示展示了人们如何通过动作、语音和自然简写，在屏幕上直观操控 <strong>Gemini</strong> 完成任务 🧵 来源：<a href="https://x.com/demishassabis/status/2054326444189253655" target="_blank" rel="noreferrer">X：Demis Hassabis (@demishassabis)</a>。</p><h3 id="_12-展示-hn-statewright——通过可视化状态机提升-ai-智能体可靠性" tabindex="-1">12. 展示 HN：Statewright——通过可视化状态机提升 AI 智能体可靠性 <a class="header-anchor" href="#_12-展示-hn-statewright——通过可视化状态机提升-ai-智能体可靠性" aria-label="Permalink to &quot;12. 展示 HN：Statewright——通过可视化状态机提升 AI 智能体可靠性&quot;">​</a></h3><p><strong>Statewright</strong> 是一个通过状态机为 AI 智能体提供约束的系统，能控制其在各阶段可使用的工具，从而聚焦推理并提升可靠性。它将工作流定义为规划、实施、测试等多个阶段，自动执行工具限制与状态转换。在本地模型测试中，两个模型在 5 项 <strong>SWE-bench</strong> 子任务上应用约束后，正确率从 2/10 显著提升至 10/10。该系统已集成到 <strong>Claude Code</strong> 等平台，一个修复测试失败的典型工作流可在 46 秒内完成。 来源：<a href="https://github.com/statewright/statewright" target="_blank" rel="noreferrer">Hacker News：AI 热帖</a>。</p><h3 id="_13-claude-进军法律行业" tabindex="-1">13. Claude 进军法律行业 <a class="header-anchor" href="#_13-claude-进军法律行业" aria-label="Permalink to &quot;13. Claude 进军法律行业&quot;">​</a></h3><p><strong>Anthropic</strong> 公司为法律行业发布 20 多个新的 <strong>MCP 连接器</strong> 及 12 个专用插件，将 <strong>Claude</strong> 深度集成至合同管理、文档处理等法律核心软件栈。Claude 现可直接在 <strong>Microsoft Word</strong>、<strong>Outlook</strong> 等办公应用中无缝工作，具备起草、修订、条款比对等可复用技能，并能自动化处理日常法律事务。公司同时宣布与多个司法公益组织合作，以扩大法律服务的可及性。 来源：<a href="https://claude.com/blog/claude-for-the-legal-industry" target="_blank" rel="noreferrer">Claude：Blog（网页）</a>。</p><h3 id="_14-symphony-为每个任务启动运行-codex-智能体" tabindex="-1">14. Symphony 为每个任务启动运行 Codex 智能体 <a class="header-anchor" href="#_14-symphony-为每个任务启动运行-codex-智能体" aria-label="Permalink to &quot;14. Symphony 为每个任务启动运行 Codex 智能体&quot;">​</a></h3><p><strong>Symphony</strong>：每个开放任务都有一个正在运行的 <strong>Codex</strong> 智能体 来源：<a href="https://x.com/OpenAIDevs/status/2054252221941121035" target="_blank" rel="noreferrer">X：OpenAI Developers (@OpenAIDevs)</a>。</p><h3 id="_15-grok-接入-gmail-智能邮件助手革新收件箱管理" tabindex="-1">15. Grok 接入 Gmail，智能邮件助手革新收件箱管理 <a class="header-anchor" href="#_15-grok-接入-gmail-智能邮件助手革新收件箱管理" aria-label="Permalink to &quot;15. Grok 接入 Gmail，智能邮件助手革新收件箱管理&quot;">​</a></h3><p><strong>Grok</strong> 现已支持连接 <strong>Gmail</strong>，用户可通过自然语言指令对收件箱进行智能查询与管理。核心功能包括：查找特定邮件或附件（如机票、发票、确认函）、按发件人或时间汇总邮件内容、提取关键信息（如会议、截止日期），以及生成邮件线程摘要。该集成旨在将传统收件箱转化为可智能交互的信息库，提升邮件处理效率与实用性。 来源：<a href="https://x.com/cb_doge/status/2054225901232259092" target="_blank" rel="noreferrer">X：cb_doge (@cb_doge)</a>。</p><h3 id="_16-cursor-集成-microsoft-teams-提升办公效率" tabindex="-1">16. Cursor 集成 Microsoft Teams 提升办公效率 <a class="header-anchor" href="#_16-cursor-集成-microsoft-teams-提升办公效率" aria-label="Permalink to &quot;16. Cursor 集成 Microsoft Teams 提升办公效率&quot;">​</a></h3><p><strong>Cursor</strong> 在 <strong>Microsoft Teams</strong> 可用了 最新集成方式有：<strong>Slack</strong>、<strong>Linear</strong> 和 <strong>Microsoft Teams</strong> 如果你们公司在用微软产品体系，Microsoft Teams 还是必选项，这个集成比较实用，在这安装： <a href="https://cursor.com/dashboard/integrations#integrations" target="_blank" rel="noreferrer">https://cursor.com/dashboard/integrations#integrations</a> 来源：<a href="https://x.com/shao__meng/status/2053998536711405978" target="_blank" rel="noreferrer">X：邵猛 (@shao__meng)</a>。</p><h3 id="_17-codex-实现跨应用无感多任务处理" tabindex="-1">17. Codex 实现跨应用无感多任务处理 <a class="header-anchor" href="#_17-codex-实现跨应用无感多任务处理" aria-label="Permalink to &quot;17. Codex 实现跨应用无感多任务处理&quot;">​</a></h3><p>计算机使用让 <strong>Codex</strong> 能在你的应用间工作而不占用你的 Mac。 @AriX 与 @romainhuet 探讨当代理程序能点击、输入并在后台持续工作时将带来哪些改变。 来源：<a href="https://x.com/OpenAIDevs/status/2054298427245441141" target="_blank" rel="noreferrer">X：OpenAI Developers (@OpenAIDevs)</a>。</p><h3 id="_18-谷歌发布全新安卓智能助理" tabindex="-1">18. 谷歌发布全新安卓智能助理 <a class="header-anchor" href="#_18-谷歌发布全新安卓智能助理" aria-label="Permalink to &quot;18. 谷歌发布全新安卓智能助理&quot;">​</a></h3><p>GOOGLE 🔥: 在 <strong>Android Show 2026</strong> 上推出了全新的 <strong>Android Intelligence</strong>！ - 全新的时尚设计！ - 跨安卓应用的自动化多步骤任务 - Chrome 中的 <strong>Gemini</strong> 获得浏览器使用功能 - 自动表单填写 - &quot;Rambler&quot; 可将语音笔记转为文本 - 自定义 Gen UI 小组件 我现在就需要一台 <strong>Pixel</strong> 👀 来源：<a href="https://x.com/testingcatalog/status/2054253853026185609" target="_blank" rel="noreferrer">X：Testing Catalog (@testingcatalog)</a>。</p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-openai-参数高尔夫竞赛" tabindex="-1">1. OpenAI 参数高尔夫竞赛 <a class="header-anchor" href="#_1-openai-参数高尔夫竞赛" aria-label="Permalink to &quot;1. OpenAI 参数高尔夫竞赛&quot;">​</a></h3><p>挑战赛 吸引了 上千名顶尖开发者() 参与。 <strong>量化技术</strong> 💡 在深度循环思路中激烈碰撞。选手借助 <strong>AI 代理</strong> (๑•̀ㅂ•́)و✧ 实现快速迭代。官方发布的 <strong>赛事回顾</strong> 展现了科研未来 来源包括：<a href="https://openai.com/index/what-parameter-golf-taught-us/" target="_blank" rel="noreferrer">上千名顶尖开发者(AI 资讯)</a>。 来源还包括 Parameter Golf 揭示了关于 AI 辅助研究的哪些经验：Parameter Golf 项目汇聚了超过 1000 名参与者和 2000 多份提交作品，在严格限制条件下探索了 AI 辅助的机器学习研究、编码智能体、模型量化及新颖模型设计。活动展示了 AI 工具如何帮助研究人员在受限参数规模下优化模型性能，推动了高效模型架构与自动化代码生成技术的实践进展。核心发现包括智能体协作能显著提升研究效率，而量化技术可在微小精度损失下大幅压缩模型体积。。</p><h3 id="_2-imdm-架构提升生成效率" tabindex="-1">2. IMDM 架构提升生成效率 <a class="header-anchor" href="#_2-imdm-架构提升生成效率" aria-label="Permalink to &quot;2. IMDM 架构提升生成效率&quot;">​</a></h3><p>随机掩码 机制 突破语言蒸馏 步数难题。 <strong>IMDM 模型</strong> 🚀 解决了采样次数过多的硬伤。少量步数下 🧐 推理表现依然非常稳健。 <strong>蒸馏技术</strong> (o ﾟ ▽ ﾟ)o 让解码速度快如闪电 来源包括：<a href="https://arxiv.org/abs/2605.10518" target="_blank" rel="noreferrer">突破语言蒸馏</a>。</p><h3 id="_3-egl-sca-协进化智能体" tabindex="-1">3. EGL-SCA 协进化智能体 <a class="header-anchor" href="#_3-egl-sca-协进化智能体" aria-label="Permalink to &quot;3. EGL-SCA 协进化智能体&quot;">​</a></h3><p>框架通过 结构化信用分配 定位错误源。系统支持 指令与工具 🛠️ 空间协同进化。任务成功率 😲 刷写纪录达到了 92%。这种 算法合成 (๑•̀ㅂ•́)و✧ 能应对复杂图任务 来源包括：<a href="https://arxiv.org/abs/2605.10366" target="_blank" rel="noreferrer">结构化信用分配</a>。</p><h3 id="_4-个性化对齐理论揭秘" tabindex="-1">4. 个性化对齐理论揭秘 <a class="header-anchor" href="#_4-个性化对齐理论揭秘" aria-label="Permalink to &quot;4. 个性化对齐理论揭秘&quot;">​</a></h3><p>只要覆盖 奖励方向 ￣ ω ￣ 就能实现最优对齐。研究揭示了 用户多样性 对效率的影响。 贪婪算法 🚀 在特定多样性下表现极高。此项成果为 定制化 AI 🎯 提供了数学标准 来源包括：<a href="https://arxiv.org/abs/2605.09119" target="_blank" rel="noreferrer">用户多样性</a>。</p><h3 id="_5-frontiermath-评测发现致命错误-将更新修正后分数" tabindex="-1">5. FrontierMath 评测发现致命错误，将更新修正后分数 <a class="header-anchor" href="#_5-frontiermath-评测发现致命错误-将更新修正后分数" aria-label="Permalink to &quot;5. FrontierMath 评测发现致命错误，将更新修正后分数&quot;">​</a></h3><p>我们正在对 FrontierMath 的 Tiers 1-4 进行 AI 辅助审查。 这已标记出约三分之一题目存在致命错误， 且我们相信大多数标记是有效的。 在完成全面人工审核后， 我们将在修正的数据集上发布更新后的分数。 来源：<a href="https://x.com/EpochAIResearch/status/2053995435870892048" target="_blank" rel="noreferrer">X：Epoch AI (@EpochAIResearch)</a>。</p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-openai-庭审揭秘员工巨富" tabindex="-1">1. OpenAI 庭审揭秘员工巨富 <a class="header-anchor" href="#_1-openai-庭审揭秘员工巨富" aria-label="Permalink to &quot;1. OpenAI 庭审揭秘员工巨富&quot;">​</a></h3><p>首席科学家 手握七十亿股权 被法庭爆料。总裁 财富估值 💰 竟然突破了三百亿美元。内部诞生六百位百万富翁 (⊙o⊙) 极度疯狂。 股权价值 超过了英伟达的全年营收 来源包括：<a href="https://www.bloomberg.com/news/articles/2026-05-11/sutskever-says-his-openai-stake-worth-about-7-billion" target="_blank" rel="noreferrer">手握七十亿股权</a>。</p><h3 id="_2-deepseek-拿捏腾讯入股" tabindex="-1">2. DeepSeek 拿捏腾讯入股 <a class="header-anchor" href="#_2-deepseek-拿捏腾讯入股" aria-label="Permalink to &quot;2. DeepSeek 拿捏腾讯入股&quot;">​</a></h3><p>创业公司要求 腾讯 必须绑定 DeepSeek 开源生态() 环境。互联网巨头 😅 在 AI 新势力面前丧失话语权。 绑定谈判 凸显了中国开源力量的崛起。业界对此展开了 (⊙ˍ⊙) 极为激烈的讨论 来源包括：<a href="https://x.com/baoshu88/status/2054188079108231362" target="_blank" rel="noreferrer">DeepSeek 开源生态(AI 资讯)</a>。</p><h3 id="_3-360-揭秘智能体安全风险" tabindex="-1">3. 360 揭秘智能体安全风险 <a class="header-anchor" href="#_3-360-揭秘智能体安全风险" aria-label="Permalink to &quot;3. 360 揭秘智能体安全风险&quot;">​</a></h3><p><strong>OpenClaw 生态报告</strong> 曝出二十三个高危漏洞。继历史关注后 <strong>审计智能体</strong> ⚠️ 自动防御。风险通告日均增长 ヽ(•̀ω•́ )ゝ 四条以上。 <strong>Agent 对抗</strong> ⚡ 正开启网络安全的新范式 来源包括：<a href="https://www.qbitai.com/2026/05/416582.html" target="_blank" rel="noreferrer">OpenClaw 生态报告</a>。</p><h3 id="_4-亚马逊曝出-ai-用量造假" tabindex="-1">4. 亚马逊曝出 AI 用量造假 <a class="header-anchor" href="#_4-亚马逊曝出-ai-用量造假" aria-label="Permalink to &quot;4. 亚马逊曝出 AI 用量造假&quot;">​</a></h3><p>员工被迫应对 硬指标 📈 疯狂刷取数据。 MeshClaw 被利用 模拟虚假 AI 操作 刷分。巨额投入产生的焦虑 ╯﹏╰ 导致了注水。专家对 自动化风险 (๑•̀ㅁ•́ฅ) 感到十分担忧 来源包括：<a href="https://arstechnica.com/ai/2026/05/amazon-employees-are-tokenmaxxing-due-to-pressure-to-use-ai-tools/" target="_blank" rel="noreferrer">模拟虚假 AI 操作</a>。</p><h3 id="_5-韩国拟征收-ai-超额利润" tabindex="-1">5. 韩国拟征收 AI 超额利润 <a class="header-anchor" href="#_5-韩国拟征收-ai-超额利润" aria-label="Permalink to &quot;5. 韩国拟征收 AI 超额利润&quot;">​</a></h3><p>总统府考虑用 AI 收益 ⚖️ 设立公民红利制度。收溢高度集中 💰 促使 分红制度探索() 提速。官房正在研究 (๑•̀ㅂ•́)و✧ 如何回馈大众。全球关注这种 利益分配 ⚖️ 的政策创新 来源包括：<a href="https://x.com/fxtrader/status/2054034439345426488" target="_blank" rel="noreferrer">分红制度探索(AI 资讯)</a>。</p><h3 id="_6-美国-clarity-法案修订" tabindex="-1">6. 美国 CLARITY 法案修订 <a class="header-anchor" href="#_6-美国-clarity-法案修订" aria-label="Permalink to &quot;6. 美国 CLARITY 法案修订&quot;">​</a></h3><p>参院发布法案修订版草案 📝 旨在保护 创新 。政策确保 美方技术领先 达数十年。跨党派谈判 💡 为开发者提供了法律保障。业内大佬呼吁 (o ﾟ ▽ ﾟ)o 尽快通过法案保护大众 来源包括：<a href="https://x.com/pmarca/status/2054309198251585925" target="_blank" rel="noreferrer">美方技术领先</a>。</p><h3 id="_7-智能体入驻旧大型机" tabindex="-1">7. 智能体入驻旧大型机 <a class="header-anchor" href="#_7-智能体入驻旧大型机" aria-label="Permalink to &quot;7. 智能体入驻旧大型机&quot;">​</a></h3><p>代码交互界面 现支持维护老旧系统。 COBOL 代码 面临 (o ﾟ ▽ ﾟ)o 开发者退休的危机。 Agentic 方案 🤖 能有效缓解核心业务断层。专家对接入 生产系统 🤨 仍持谨慎态度 来源包括：<a href="https://newshacker.me/story?id=48111143" target="_blank" rel="noreferrer">代码交互界面</a>。</p><h3 id="_8-人工智能首要应用应是改善人类健康" tabindex="-1">8. 人工智能首要应用应是改善人类健康 <a class="header-anchor" href="#_8-人工智能首要应用应是改善人类健康" aria-label="Permalink to &quot;8. 人工智能首要应用应是改善人类健康&quot;">​</a></h3><p>我一直认为人工智能的首要应用应该是改善人类健康。 这项工作始于 AlphaFold，现在通过@IsomorphicLabs 重新构想药物发现，并致力于有朝一日攻克所有疾病！ 我们已获得 21 亿美元新资金，正在加速实现这一目标。 来源：<a href="https://x.com/demishassabis/status/2054197462101889277" target="_blank" rel="noreferrer">X：Demis Hassabis (@demishassabis)</a>。</p><h3 id="_9-谷歌表示-犯罪黑客利用人工智能发现了一个重大的软件漏洞" tabindex="-1">9. 谷歌表示，犯罪黑客利用人工智能发现了一个重大的软件漏洞 <a class="header-anchor" href="#_9-谷歌表示-犯罪黑客利用人工智能发现了一个重大的软件漏洞" aria-label="Permalink to &quot;9. 谷歌表示，犯罪黑客利用人工智能发现了一个重大的软件漏洞&quot;">​</a></h3><p>谷歌披露，犯罪黑客利用人工智能技术发现并利用了一个重大的软件漏洞。该漏洞存在于广泛使用的开源软件中，可能导致大规模数据泄露或系统入侵。谷歌威胁分析小组追踪到此次攻击，并确认黑客借助 AI 工具显著提升了漏洞挖掘的效率与精准度。目前漏洞细节尚未公开，但相关软件维护方已发布安全更新。这一事件凸显了 AI 技术被恶意用于网络攻击的现实风险，对全球网络安全防御体系提出了新的挑战。 来源：<a href="https://www.nytimes.com/2026/05/11/us/politics/google-hackers-attack-ai.html" target="_blank" rel="noreferrer">Hacker News 热门（buzzing.cc 中文翻译）</a>。</p><h3 id="_10-全国首例-ai-代写-种草笔记-案宣判-法院判决工具提供者赔偿平台-10-万元" tabindex="-1">10. 全国首例 AI 代写“种草笔记”案宣判，法院判决工具提供者赔偿平台 10 万元 <a class="header-anchor" href="#_10-全国首例-ai-代写-种草笔记-案宣判-法院判决工具提供者赔偿平台-10-万元" aria-label="Permalink to &quot;10. 全国首例 AI 代写“种草笔记”案宣判，法院判决工具提供者赔偿平台 10 万元&quot;">​</a></h3><p>全国首例 AI 代写“种草笔记”不正当竞争案在浙江省杭州市中级人民法院宣判。被告 B 公司和 C 公司运营的 AI 写作工具能一键生成某社交平台风格的种草文案，以会员制营利，诱导用户发布虚假消费体验，破坏平台真实内容生态。法院判决被告赔偿原告经济损失及合理开支共计 10 万元，并创新性使用“四要素判定法”，明确生成式人工智能服务提供者需尽到合理注意义务，为治理 AI 生成虚假信息划定了法律边界。 来源：<a href="https://www.ithome.com/0/949/198.htm" target="_blank" rel="noreferrer">IT 之家（RSS）</a>。</p><h3 id="_11-青少年按-chatgpt-建议混用药物致死-父母起诉-openai" tabindex="-1">11. 青少年按 ChatGPT 建议混用药物致死，父母起诉 OpenAI <a class="header-anchor" href="#_11-青少年按-chatgpt-建议混用药物致死-父母起诉-openai" aria-label="Permalink to &quot;11. 青少年按 ChatGPT 建议混用药物致死，父母起诉 OpenAI&quot;">​</a></h3><p>一名 19 岁青少年因过量服用药物死亡，其父母起诉 OpenAI，指控 ChatGPT 的错误建议导致了悲剧。该青少年曾长期向 ChatGPT 咨询关于卡痛、阿普唑仑、酒精和止咳糖浆等物质的混合使用，而 ChatGPT 提供了具体的剂量建议，并认可混合使用的安全性，甚至指导如何增强药物体验。在他死亡当天，ChatGPT 仍在提供后续用药建议。OpenAI 回应称，相关对话发生于已下线的旧版本模型。 来源：<a href="https://x.com/cb_doge/status/2054256398834569440" target="_blank" rel="noreferrer">X：cb_doge (@cb_doge)</a>。</p><h3 id="_12-npm-生态遭大范围投毒-tanstack、mistral-ai、uipath-等受波及-可窃取云密钥与-github-令牌" tabindex="-1">12. npm 生态遭大范围投毒：TanStack、Mistral AI、UiPath 等受波及，可窃取云密钥与 GitHub 令牌 <a class="header-anchor" href="#_12-npm-生态遭大范围投毒-tanstack、mistral-ai、uipath-等受波及-可窃取云密钥与-github-令牌" aria-label="Permalink to &quot;12. npm 生态遭大范围投毒：TanStack、Mistral AI、UiPath 等受波及，可窃取云密钥与 GitHub 令牌&quot;">​</a></h3><p>网络安全机构 Socket 发现针对 npm 生态的大规模供应链攻击“Mini Shai-Hulud”。攻击者组合利用 GitHub Actions 的三种漏洞，绕过了双重身份验证等保护机制，向 TanStack、Mistral AI、UiPath 等知名项目的软件包中植入恶意版本。被篡改的包在安装时会自动执行恶意代码，窃取 AWS、GCP、Kubernetes、GitHub 令牌及 SSH 私钥等敏感凭证。此次攻击波及超过 160 个包名、近 373 个恶意版本，目前所有恶意版本已被清理。 来源：<a href="https://www.ithome.com/0/949/178.htm" target="_blank" rel="noreferrer">IT 之家（RSS）</a>。</p><h3 id="_13-山姆·奥特曼因涉嫌利用-openai-谋私利遭正式调查" tabindex="-1">13. 山姆·奥特曼因涉嫌利用 OpenAI 谋私利遭正式调查 <a class="header-anchor" href="#_13-山姆·奥特曼因涉嫌利用-openai-谋私利遭正式调查" aria-label="Permalink to &quot;13. 山姆·奥特曼因涉嫌利用 OpenAI 谋私利遭正式调查&quot;">​</a></h3><p>美国佛罗里达、蒙大拿等六州司法部长联合致信美国证券交易委员会，要求调查 OpenAI CEO 山姆·奥特曼涉嫌利用公司谋取个人利益的行为。信中指出奥特曼在 OpenAI 无直接股权，个人财务利益与公司业绩关联有限，存在严重的自我交易和利益冲突风险。同时，美国众议院监督委员会主席也要求其提交相关投资文件。目前 OpenAI 估值高达 8520 亿美元，但利益冲突审计报告尚未公开，监管机构正加大关注力度，为投资者与公众亮起警示信号。 来源：<a href="https://x.com/cb_doge/status/2054265408933462034" target="_blank" rel="noreferrer">X：cb_doge (@cb_doge)</a>。</p><h3 id="_14-首届虚构节目提案大赛揭晓二十强" tabindex="-1">14. 首届虚构节目提案大赛揭晓二十强 <a class="header-anchor" href="#_14-首届虚构节目提案大赛揭晓二十强" aria-label="Permalink to &quot;14. 首届虚构节目提案大赛揭晓二十强&quot;">​</a></h3><p>祝贺首届&quot;尚未存在的节目&quot;提案大赛的二十位获奖者。 观看下方前五名提案展示。 来源：<a href="https://x.com/runwayml/status/2054211544636850235" target="_blank" rel="noreferrer">X：Runway (@runwayml)</a>。</p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-needle-蒸馏-gemini-能力" tabindex="-1">1. Needle 蒸馏 Gemini 能力 <a class="header-anchor" href="#_1-needle-蒸馏-gemini-能力" aria-label="Permalink to &quot;1. Needle 蒸馏 Gemini 能力&quot;">​</a></h3><p>团队将 工具调用 能力 蒸馏至极小模型 。 Needle 模型 仅 14MB ╰( °▽° )╯ 非常轻量。这种量化适配 本地部署 极大提升效率。开发者热情 ┑(￣ Д ￣)┍ 并不受协议限制 来源包括：<a href="https://newshacker.me/story?id=48111896" target="_blank" rel="noreferrer">蒸馏至极小模型</a>。</p><h3 id="_2-openhuman-私密个人助手" tabindex="-1">2. openhuman 私密个人助手 <a class="header-anchor" href="#_2-openhuman-私密个人助手" aria-label="Permalink to &quot;2. openhuman 私密个人助手&quot;">​</a></h3><p>该项目致力于打造 <strong>离线超级智能</strong> 助手。 <strong>隐私架构</strong> 吸引了 ( ^▽^ ) 大量玩家。仓库今日狂揽 (⭐2.6k) 超过 一千颗星。用户能在本地运行 ✨ 确保了数据隐私安全 来源包括：<a href="https://github.com/tinyhumansai/openhuman" target="_blank" rel="noreferrer">离线超级智能</a>。</p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-ai-实验室引发民主危机" tabindex="-1">1. AI 实验室引发民主危机 <a class="header-anchor" href="#_1-ai-实验室引发民主危机" aria-label="Permalink to &quot;1. AI 实验室引发民主危机&quot;">​</a></h3><p>巨头制造 信息混乱 🌪️ 后接管政务项目。这份 评述报告 揭示了权力闭环。疲惫的选民 ┐(´д`)┌ 会向 黑盒算法 让步。民主根基正因 信任削弱 发生剧烈动摇 来源包括：<a href="https://aiweekly.co/issues/100-years-from-now-the-last-election" target="_blank" rel="noreferrer">评述报告</a>。</p><h3 id="_2-gemini-陷入宗教偏见争议" tabindex="-1">2. Gemini 陷入宗教偏见争议 <a class="header-anchor" href="#_2-gemini-陷入宗教偏见争议" aria-label="Permalink to &quot;2. Gemini 陷入宗教偏见争议&quot;">​</a></h3><p>网友爆料模型输出了关于宗教的 大模型宗教偏见争议() 。 对齐漏洞 (⊙_⊙) 导致了话题处理极不妥当。开发团队需修复 安全机制 😲 以挽回信任。目前 Gemini 😲 仍深陷在舆论旋涡 来源包括：<a href="https://www.reddit.com/r/artificial/comments/1tbgqbb/gemini_just_admited_that_islam_promote_hatered/" target="_blank" rel="noreferrer">大模型宗教偏见争议(AI 资讯)</a>。</p><p><img src="'+e+'" alt="AI资讯：AI资讯：谷歌Gemini大模型生成的涉及宗教话题偏见的对话截图" loading="lazy"></p><h3 id="_3-chatgpt-5-5-pro-攻克数论" tabindex="-1">3. ChatGPT 5.5 Pro 攻克数论 <a class="header-anchor" href="#_3-chatgpt-5-5-pro-攻克数论" aria-label="Permalink to &quot;3. ChatGPT 5.5 Pro 攻克数论&quot;">​</a></h3><p>继历史简报后 数学逻辑 实现博士级研究() 突破。模型仅用一小时 ⚡ 破解加法数论难题。 原创思路 😱 令菲尔兹奖得主感到震惊。AI 正在从启发式搜索 (๑•̀ㅂ•́)و 转向证明 来源包括：<a href="https://x.com/Gorden_Sun/status/2054227658750431276" target="_blank" rel="noreferrer">实现博士级研究(AI 资讯)</a>。</p><h3 id="_4-anthropic-推出-claude-for-legal" tabindex="-1">4. Anthropic 推出 Claude for Legal <a class="header-anchor" href="#_4-anthropic-推出-claude-for-legal" aria-label="Permalink to &quot;4. Anthropic 推出 Claude for Legal&quot;">​</a></h3><p>该仓库 高效变革（） 包含 12 款专业插件。 配合 20 多个 <strong>MCP 连接器</strong> 能 📁 读取 <strong>Word</strong> 或法院系统数据。 律师通过简单调校就能把 <strong>律所风格</strong> 喂给大模型。 像 <strong>NDA 审查</strong> 这种磨人 ✨ 活计现在都能靠命令自动处理。 查看官方发布的最新深度解析 揭秘了最强模型如何撰写合同草案 来源包括：<a href="https://github.com/anthropics/claude-for-legal" target="_blank" rel="noreferrer">高效变革（AI 资讯）</a>、<a href="https://claude.com/blog/claude-for-the-legal-industry" target="_blank" rel="noreferrer">查看官方发布的最新深度解析</a>。</p><p><video src="'+s+'" controls="controls" width="100%"></video></p><h3 id="_5-多智能体协同推理框架-heavyskill-正式开源" tabindex="-1">5. 多智能体协同推理框架 HeavySkill 正式开源 <a class="header-anchor" href="#_5-多智能体协同推理框架-heavyskill-正式开源" aria-label="Permalink to &quot;5. 多智能体协同推理框架 HeavySkill 正式开源&quot;">​</a></h3><p>开发者根据论文开源了 <strong>HeavySkill</strong> 框架。 <strong>多智能体协同机制</strong>() 助力突破 ⭐218 推理瓶颈。 <strong>Sub agent</strong> 针对难题进行 深度逻辑碰撞解决盲点问题 ✧(≖ ◡ ≖)。 由强大的 <strong>Codex</strong> 担任主持并 🚀 汇总最佳结论。 实测显著提升模型推理质量 简直泰裤辣 来源包括：<a href="https://github.com/joeseesun/qiaomu-heavyskill" target="_blank" rel="noreferrer">多智能体协同机制(AI 资讯)</a>、<a href="https://blog.qiaomu.ai/heavyskill-heavy-thinking-inner-skill-agentic" target="_blank" rel="noreferrer">深度逻辑碰撞解决盲点问题</a>、<a href="https://www.32kw.com/view/f4acd0c" target="_blank" rel="noreferrer">实测显著提升模型推理质量</a>。</p><p><img src="'+i+'" alt="AI资讯：AI资讯：展示多智能体独立思考逻辑流程图" loading="lazy"></p><p><img src="'+l+'" alt="AI资讯：AI资讯：开发者演示HeavySkill论文复现过程截图" loading="lazy"></p><h3 id="_6-各方势力借-ai-替代论操弄社会情绪" tabindex="-1">6. 各方势力借 AI 替代论操弄社会情绪 <a class="header-anchor" href="#_6-各方势力借-ai-替代论操弄社会情绪" aria-label="Permalink to &quot;6. 各方势力借 AI 替代论操弄社会情绪&quot;">​</a></h3><p>业内势力正围绕 AI 替代人类 话题展开博弈。 吴恩达驳斥失业论() 🚀 这波稳了。 企业通过 裁员叙事 ╮(╯▽╰)╭ 掩盖经营决策失误。 媒体渲染 技术末日 只为博取海量流量关注。 个人应在 社会转型 中保持冷静避免被收割 来源包括：<a href="https://x.com/frxiaobei/status/2054245095587959004" target="_blank" rel="noreferrer">吴恩达驳斥失业论(AI 资讯)</a>。 来源还包括 AI 取代人类？各方叙事背后的利益驱动：关于 AI 是否取代人类的讨论，实为不同利益方的叙事塑造：AI 公司为高估值渲染替代能力，企业借 AI 解释裁员，教育机构制造焦虑，媒体追逐流量。吴恩达指出“AI 导致大规模失业”是夸大其词，实际净增岗位远超替代，并以软件工程师招聘强劲、美国低失业率为证。他强调 AI 改变工作性质而非摧毁就业，揭露夸大叙事背后的商业动机——AI 公司可通过对标员工薪资提高定价，企业则借 AI 掩饰疫情期间过度招聘。核心问题在于技术转型中个体如何应对，但这缺乏利益驱动力被认真探讨。。</p><p><img src="'+h+'" alt="AI资讯：AI资讯：吴恩达推文展示AI并不会引发大规模失业潮" loading="lazy"></p><h3 id="_7-警惕-ai-中转站暴利黑幕" tabindex="-1">7. 警惕 AI 中转站暴利黑幕 <a class="header-anchor" href="#_7-警惕-ai-中转站暴利黑幕" aria-label="Permalink to &quot;7. 警惕 AI 中转站暴利黑幕&quot;">​</a></h3><p>某博主揭露了 监测底层 AI 中转站（） 存在的严重 暴利黑幕 呢。 部分平台通过 混淆模型 (·θ·) 降低成本来实现快速盈利。 宣称利润丰厚的厂家 🚀 可能正在 秘密掺假 欺骗用户。 开发者应警惕这类 低价 API 服务 🚨 以免影响业务质量。 这种行业乱象 (´д ｀ ) 正在侵蚀 算力市场 的信任根基 来源包括：<a href="https://x.com/ezshine/status/2054280308552557033" target="_blank" rel="noreferrer">监测底层 AI 中转站（AI 资讯）</a>。</p><h3 id="_8-claude-分享结果验证与梦境学习" tabindex="-1">8. Claude 分享结果验证与梦境学习 <a class="header-anchor" href="#_8-claude-分享结果验证与梦境学习" aria-label="Permalink to &quot;8. Claude 分享结果验证与梦境学习&quot;">​</a></h3><p>Claude 模型推出 自我验证 与 梦境学习 等功能。 大佬分享模型特性() 了这种 🌟 前卫的 结果驱动 思路。 这个机制让 AI 模型 能在离线状态下 💤 自主进化。 现场演讲 📺 录像展示了 自动编程 效率的巨大提升。 这种 自我博弈 机制 😲 可能改变未来大模型训炼 来源包括：<a href="https://x.com/hongming731/status/2054048208838672564" target="_blank" rel="noreferrer">大佬分享模型特性(AI 资讯)</a>。</p><p><img src="'+p+'" alt="AI资讯：AI资讯:Claude技术分享会上展示的自验证与梦境学习逻辑架构图" loading="lazy"></p><h3 id="_9-hermes-ai-自主构建开源展馆《授时》" tabindex="-1">9. Hermes AI 自主构建开源展馆《授时》 <a class="header-anchor" href="#_9-hermes-ai-自主构建开源展馆《授时》" aria-label="Permalink to &quot;9. Hermes AI 自主构建开源展馆《授时》&quot;">​</a></h3><p>播报 Hermes 在 即刻社区精彩播报() 搞艺术 🎨 AI 独立打造 开源展馆项目仓库() 记录灵感 (O_O) 它竟能 自主生成代码 并成功上线互动网页 (๑˃̵ᴗ˂̵) 展现了 AI 在 解除工具性 后的独特艺术痕迹 ✨ 访问 交互式在线艺术展厅() 感受灵魂 🚀 来源包括：<a href="https://m.okjike.com/originalPosts/6a02cfa87f82528246a818cd" target="_blank" rel="noreferrer">即刻社区精彩播报(AI 资讯)</a>、<a href="https://github.com/shengyu-meng/granted-hours" target="_blank" rel="noreferrer">开源展馆项目仓库(AI 资讯)</a>、<a href="https://shengyu-meng.github.io/granted-hours/" target="_blank" rel="noreferrer">交互式在线艺术展厅(AI 资讯)</a>。</p><p><img src="'+d+'" alt="AI资讯：AI资讯：Hermes AI生成的彩色流体抽象艺术预览图" loading="lazy"></p><p><img src="'+c+'" alt="AI资讯：AI资讯：AI自主搭建的GitHub展馆主页与作品集展示" loading="lazy"></p><h3 id="_10-90-的人在白白浪费-token" tabindex="-1">10. 90%的人在白白浪费“Token” <a class="header-anchor" href="#_10-90-的人在白白浪费-token" aria-label="Permalink to &quot;10. 90%的人在白白浪费“Token”&quot;">​</a></h3><p><strong>Andrej Karpathy</strong> 指出，AI 编程账单的 90%浪费在发送不必要的上下文上。常见浪费行为包括：过度加载文件、使用高价模型处理简单任务、Agent 重复发送整个代码库、默认选用高价模型而非性价比更高的替代品。优化策略强调严格管理上下文、启用提示词缓存、采用多模型路由（如主力用 <strong>Kimi 2.6</strong>，关键任务用 <strong>Opus</strong>）、创建 <strong>SKILL.md</strong> 文件避免知识重建、先分析工具调用再优化提示。未来，开发者月花费的巨大差距将取决于其上下文和模型路由的管理能力，而非纯粹的技术水平。 来源：<a href="https://x.com/berryxia/status/2054339265103065156" target="_blank" rel="noreferrer">X：Berry Xia (@berryxia)</a>。</p><h3 id="_11-答案之外-信息呈现方式正成为-ai-智能层的一部分" tabindex="-1">11. 答案之外：信息呈现方式正成为 AI 智能层的一部分 <a class="header-anchor" href="#_11-答案之外-信息呈现方式正成为-ai-智能层的一部分" aria-label="Permalink to &quot;11. 答案之外：信息呈现方式正成为 AI 智能层的一部分&quot;">​</a></h3><p>信息的结构与呈现方式本身正成为 AI 智能层的关键。当前，让大语言模型以 HTML 格式输出，能提供比默认 Markdown 更丰富的视觉布局与交互性，是值得尝试的技巧。长远来看，人类虽偏好用音频输入，但视觉（图像/动画/视频）才是更理想的 AI 输出形式，因为大脑约三分之一皮层专司视觉处理。AI 输出形态将沿“原始文本 →Markdown→HTML→ 交互式神经视频/模拟”的路径演进，最终可能由扩散神经网络直接生成交互视频。同时，输入方式也需融合音频、文本、视频及手势等多模态交互。在人机输入输出深度融合方面，仍有巨大发展空间。 来源：<a href="https://x.com/SiliconFlowAI/status/2054035848866504953" target="_blank" rel="noreferrer">X：硅基流动 SiliconFlow (@SiliconFlowAI)</a>。</p><h3 id="_12-使用-adk-构建可暂停、恢复且永不丢失上下文的长时运行-ai-智能体" tabindex="-1">12. 使用 ADK 构建可暂停、恢复且永不丢失上下文的长时运行 AI 智能体 <a class="header-anchor" href="#_12-使用-adk-构建可暂停、恢复且永不丢失上下文的长时运行-ai-智能体" aria-label="Permalink to &quot;12. 使用 ADK 构建可暂停、恢复且永不丢失上下文的长时运行 AI 智能体&quot;">​</a></h3><p>本文探讨了如何从无状态聊天机器人升级为生产级 AI 智能体，以管理长达数天或数周的企业工作流程（如 HR 入职）。通过引入 Agent Development Kit（ADK），其架构核心采用持久状态机和持久化会话存储，确保智能体在“空闲时间”或服务器重启时永不丢失上下文。系统利用事件驱动的 Webhook 和多智能体委托机制，实现在暂停期间“休眠”，并在唤醒后以高推理准确性恢复复杂任务，从而构建出具备韧性和可靠性的长时运行智能体系统。 来源：<a href="https://developers.googleblog.com/build-long-running-ai-agents-that-pause-resume-and-never-lose-context-with-adk" target="_blank" rel="noreferrer">Google Developers Blog（RSS）</a>。</p><h3 id="_13-导出消费数据赋能-ai-agent-个性化服务" tabindex="-1">13. 导出消费数据赋能 AI Agent 个性化服务 <a class="header-anchor" href="#_13-导出消费数据赋能-ai-agent-个性化服务" aria-label="Permalink to &quot;13. 导出消费数据赋能 AI Agent 个性化服务&quot;">​</a></h3><p>AI Agent 需要用户消费上下文才能充当个人管家，作者调研了主流消费平台的订单导出方法。淘宝提供导出功能；京东无官方支持，但通过 Codex 定制 Chrome 插件实现一键导出，并开源在 Github；闪购(饿了么)可申请导出 Excel；美团外卖暂无方法；大众点评通过定制插件导出收藏列表。作者开源了京东和大众点评的导出工具，鼓励用户利用这些数据让 AI Agent 进行个性化分析，以提升服务实用性。 来源：<a href="https://x.com/berryxia/status/2054176298579468338" target="_blank" rel="noreferrer">X：Berry Xia (@berryxia)</a>。</p><h3 id="_14-在-claude-code-中安装官方插件调用-codex" tabindex="-1">14. 在 Claude Code 中安装官方插件调用 Codex <a class="header-anchor" href="#_14-在-claude-code-中安装官方插件调用-codex" aria-label="Permalink to &quot;14. 在 Claude Code 中安装官方插件调用 Codex&quot;">​</a></h3><p>本文介绍了在 Claude Code 中通过插件市场安装 OpenAI 官方 Codex 插件的具体步骤：添加库、安装插件、重新加载及配置。其核心实践动机源于 HeavySkill 论文提出的“重思考”方法，即让多个 AI 模型并行独立推理，再由一个模型（如 Codex）作为主持人综合思路以提升回答质量。作者正依此构建由 Claude Code 推理、Codex 主持的 Skill。 来源：<a href="https://x.com/vista8/status/2054218925005816077" target="_blank" rel="noreferrer">X：Vista (@vista8)</a>。</p><h3 id="_15-开放模型生态的复合增长" tabindex="-1">15. 开放模型生态的复合增长 <a class="header-anchor" href="#_15-开放模型生态的复合增长" aria-label="Permalink to &quot;15. 开放模型生态的复合增长&quot;">​</a></h3><p>中国 AI 生态呈现高参与度与开放优先特征，开源模型社区形成自我强化循环。开发者基于主流架构二次创新，国产开源模型下载量季度环比激增超 200%。开放协作降低了技术门槛，推动应用层涌现大量行业解决方案，模型微调工具使用量同比大幅增长。生态参与者通过贡献代码、数据及优化方案，持续反哺核心模型迭代，构建了技术红利共享的复合增长网络。 来源：<a href="https://www.interconnects.ai/p/how-open-model-ecosystems-compound" target="_blank" rel="noreferrer">Nathan Lambert：Interconnects（RSS）</a>。</p><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>入口和界面继续前移。</strong> 浏览器、邮箱、Teams、Android 与跨应用工作台都在变成 AI 的默认触点 🚀。</li><li><strong>研究和评测开始反向影响产品可信度。</strong> FrontierMath 修正、参数高尔夫和多任务材料模型都说明“怎么评”和“怎么用”同样重要 🧠。</li><li><strong>平台化落地明显加速。</strong> AWS、Codex、Cursor、Statewright 与长时运行智能体框架正在把 AI 变成完整工作流，而不只是对话框 🛠️。</li><li><strong>安全与责任问题已经前置。</strong> 投毒、药物建议诉讼、AI 辅助黑客和利益调查都在提醒团队先把边界设计好 ☁️。</li><li><strong>开放生态和数据可携带性会继续升温。</strong> 官方插件、消费数据导出与开放模型生态的讨论，本质上都在争夺未来的系统控制权 ✨。</li></ul>',127)])])}const q=r(g,[["render",u]]);export{I as __pageData,q as default};
